65	impl SymLink {
66	    /// Plan a symlink operation by probing the filesystem.
67	    ///
68	    /// # Arguments
69	    /// * `cwd`: current working directory (used to derive the symlink name)
70	    /// * `target`: the directory the symlink should point to (resolved to absolute)
71	    /// * `symlink_dir`: parent directory for the symlink (e.g. `~/.claude/projects`)
72	    pub fn new(cwd: &Path, target: &Path, symlink_dir: &Path) -> Result<Self, String> {
73	        // Claude Code names a project by its real working directory,
74	        // which has no `.` or `..` in it, so the name is derived from
75	        // the same shape whatever the caller passed.
76	        let cwd = &crate::common::normalize_path(cwd);
77	        let abs_target = crate::common::normalize_path(&if target.is_absolute() {
78	            target.to_path_buf()
79	        } else {
80	            cwd.join(target)
81	        });
82	
83	        let cwd_str = cwd
84	            .to_str()
85	            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
86	        let symlink_name = encode_path(cwd_str);
87	        let symlink_path = symlink_dir.join(symlink_name);
88	
89	        let action = match probe(&symlink_path) {
90	            None => SymlinkAction::Create,
91	            Some(None) => {
92	                return Err(format!(
93	                    "'{}' exists and is not a symlink",
94	                    symlink_path.display()
95	                ));
96	            }
97	            Some(Some(current_target)) => {
98	                if current_target == abs_target {
99	                    SymlinkAction::AlreadyCorrect
100	                } else {
101	                    SymlinkAction::Replace { current_target }
102	                }
103	            }
104	        };
105	
106	        Ok(SymLink {
107	            abs_target,
108	            symlink_path,
109	            action,
110	        })
111	    }
112	
113	    /// Plan a symlink operation from pre-probed metadata (for testing).
114	    #[cfg(test)]
115	    pub fn with_meta(
116	        cwd: &Path,
117	        target: &Path,
118	        symlink_dir: &Path,
119	        symlink_meta: Option<Option<PathBuf>>,
120	    ) -> Result<Self, String> {
121	        // Claude Code names a project by its real working directory,
122	        // which has no `.` or `..` in it, so the name is derived from
123	        // the same shape whatever the caller passed.
124	        let cwd = &crate::common::normalize_path(cwd);
125	        let abs_target = crate::common::normalize_path(&if target.is_absolute() {
126	            target.to_path_buf()
127	        } else {
128	            cwd.join(target)
129	        });
130	
131	        let cwd_str = cwd
132	            .to_str()
133	            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
134	        let symlink_name = encode_path(cwd_str);
135	        let symlink_path = symlink_dir.join(symlink_name);
136	
137	        let action = match symlink_meta {
138	            None => SymlinkAction::Create,
139	            Some(None) => {
140	                return Err(format!(
141	                    "'{}' exists and is not a symlink",
142	                    symlink_path.display()
143	                ));
144	            }
145	            Some(Some(current_target)) => {
146	                if current_target == abs_target {
147	                    SymlinkAction::AlreadyCorrect
148	                } else {
149	                    SymlinkAction::Replace { current_target }
150	                }
151	            }
152	        };
153	
154	        Ok(SymLink {
155	            abs_target,
156	            symlink_path,
157	            action,
158	        })
159	    }
160	
161	    /// Execute the symlink operation: create the target dir if needed, create/replace the symlink.
162	    pub fn create(&self, create_target: bool) -> Result<(), String> {
163	        debug!(
164	            "symlink {} -> {}",
165	            self.symlink_path.display(),
166	            self.abs_target.display()
167	        );
168	
169	        if create_target && !self.abs_target.exists() {
170	            std::fs::create_dir_all(&self.abs_target).map_err(|e| {
171	                format!("cannot create target '{}': {e}", self.abs_target.display())
172	            })?;
173	        }
174	
175	        if let Some(parent) = self.symlink_path.parent() {
176	            std::fs::create_dir_all(parent).map_err(|e| {
177	                format!(
178	                    "cannot create symlink directory '{}': {e}",
179	                    parent.display()
180	                )
181	            })?;
182	        }
183	
184	        match &self.action {
185	            SymlinkAction::Create => {}
186	            SymlinkAction::Replace { .. } => {
187	                std::fs::remove_file(&self.symlink_path).map_err(|e| {
188	                    format!(
189	                        "cannot remove existing symlink '{}': {e}",
190	                        self.symlink_path.display()
191	                    )
192	                })?;
193	            }
194	            SymlinkAction::AlreadyCorrect => return Ok(()),
195	        }
196	
197	        #[cfg(unix)]
198	        std::os::unix::fs::symlink(&self.abs_target, &self.symlink_path).map_err(|e| {
199	            format!(
200	                "cannot create symlink '{}' -> '{}': {e}",
201	                self.symlink_path.display(),
202	                self.abs_target.display()
203	            )
204	        })?;
205	
206	        #[cfg(not(unix))]
207	        return Err("symlink creation is only supported on Unix".to_string());
208	
209	        Ok(())
210	    }
211	}
