213	/// `~/.claude/projects/`: the standard Claude Code symlink
214	/// directory. Shared default for `install` and the
215	/// `vc-x1 symlink` subcommand.
216	fn default_symlink_dir() -> Result<PathBuf, Box<dyn std::error::Error>> {
217	    let home =
218	        std::env::var("HOME").map_err(|_| "HOME environment variable not set".to_string())?;
219	    Ok(PathBuf::from(home).join(".claude").join("projects"))
220	}
221	
222	/// Install the standard Claude Code workspace symlink for `project_dir`.
223	///
224	/// Links `~/.claude/projects/<encoded>` -> `<project_dir>/.claude`.
225	/// Silent: caller is expected to announce the action (if desired)
226	/// and to include the resulting `SymLink` in any final summary
227	/// output.
228	///
229	/// Shared by `vc-x1 clone --scope=work,bot` and `vc-x1 init
230	/// --scope=work,bot`. The full `vc-x1 symlink` subcommand below
231	/// can't directly call `install`: it has different
232	/// responsibilities (`--target` / `--symlink-dir` overrides,
233	/// replace prompts, `--list`, and `sl.create(true)` vs `false`),
234	/// but both share `default_symlink_dir` for default-path
235	/// computation.
236	pub fn install(project_dir: &Path) -> Result<SymLink, Box<dyn std::error::Error>> {
237	    let sl = SymLink::new(
238	        project_dir,
239	        &default_bot_target(project_dir),
240	        &default_symlink_dir()?,
241	    )?;
242	    sl.create(false)?;
243	    Ok(sl)
244	}
245	
246	/// Default symlink target: the workspace config's bot dir name,
247	/// honoring a legacy-schema declaration (the clone
248	/// backward-compat path), falling back to `.claude` when no
249	/// config resolves (e.g. mid-init before both sides exist).
250	fn default_bot_target(project_dir: &Path) -> PathBuf {
251	    crate::common::configured_bot_dir(project_dir)
252	        .ok()
