impl SymLink {
    /// Plan a symlink operation by probing the filesystem.
    ///
    /// # Arguments
    /// * `cwd`: current working directory (used to derive the symlink name)
    /// * `target`: the directory the symlink should point to (resolved to absolute)
    /// * `symlink_dir`: parent directory for the symlink (e.g. `~/.claude/projects`)
    pub fn new(cwd: &Path, target: &Path, symlink_dir: &Path) -> Result<Self, String> {
        // Claude Code names a project by its real working directory,
        // which has no `.` or `..` in it, so the name is derived from
        // the same shape whatever the caller passed.
        let cwd = &crate::common::normalize_path(cwd);
        let abs_target = crate::common::normalize_path(&if target.is_absolute() {
            target.to_path_buf()
        } else {
            cwd.join(target)
        });

        let cwd_str = cwd
            .to_str()
            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
        let symlink_name = encode_path(cwd_str);
        let symlink_path = symlink_dir.join(symlink_name);

        let action = match probe(&symlink_path) {
            None => SymlinkAction::Create,
            Some(None) => {
                return Err(format!(
                    "'{}' exists and is not a symlink",
                    symlink_path.display()
                ));
            }
            Some(Some(current_target)) => {
                if current_target == abs_target {
                    SymlinkAction::AlreadyCorrect
                } else {
                    SymlinkAction::Replace { current_target }
                }
            }
        };

        Ok(SymLink {
            abs_target,
            symlink_path,
            action,
        })
    }

    /// Plan a symlink operation from pre-probed metadata (for testing).
    #[cfg(test)]
    pub fn with_meta(
        cwd: &Path,
        target: &Path,
        symlink_dir: &Path,
        symlink_meta: Option<Option<PathBuf>>,
    ) -> Result<Self, String> {
        // Claude Code names a project by its real working directory,
        // which has no `.` or `..` in it, so the name is derived from
        // the same shape whatever the caller passed.
        let cwd = &crate::common::normalize_path(cwd);
        let abs_target = crate::common::normalize_path(&if target.is_absolute() {
            target.to_path_buf()
        } else {
            cwd.join(target)
        });

        let cwd_str = cwd
            .to_str()
            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
        let symlink_name = encode_path(cwd_str);
        let symlink_path = symlink_dir.join(symlink_name);

        let action = match symlink_meta {
            None => SymlinkAction::Create,
            Some(None) => {
                return Err(format!(
                    "'{}' exists and is not a symlink",
                    symlink_path.display()
                ));
            }
            Some(Some(current_target)) => {
                if current_target == abs_target {
                    SymlinkAction::AlreadyCorrect
                } else {
                    SymlinkAction::Replace { current_target }
                }
            }
        };

        Ok(SymLink {
            abs_target,
            symlink_path,
            action,
        })
    }

    /// Execute the symlink operation: create the target dir if needed, create/replace the symlink.
    pub fn create(&self, create_target: bool) -> Result<(), String> {
        debug!(
            "symlink {} -> {}",
            self.symlink_path.display(),
            self.abs_target.display()
        );

        if create_target && !self.abs_target.exists() {
            std::fs::create_dir_all(&self.abs_target).map_err(|e| {
                format!("cannot create target '{}': {e}", self.abs_target.display())
            })?;
        }

        if let Some(parent) = self.symlink_path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| {
                format!(
                    "cannot create symlink directory '{}': {e}",
                    parent.display()
                )
            })?;
        }

        match &self.action {
            SymlinkAction::Create => {}
            SymlinkAction::Replace { .. } => {
                std::fs::remove_file(&self.symlink_path).map_err(|e| {
                    format!(
                        "cannot remove existing symlink '{}': {e}",
                        self.symlink_path.display()
                    )
                })?;
            }
            SymlinkAction::AlreadyCorrect => return Ok(()),
        }

        #[cfg(unix)]
        std::os::unix::fs::symlink(&self.abs_target, &self.symlink_path).map_err(|e| {
            format!(
                "cannot create symlink '{}' -> '{}': {e}",
                self.symlink_path.display(),
                self.abs_target.display()
            )
        })?;

        #[cfg(not(unix))]
        return Err("symlink creation is only supported on Unix".to_string());

        Ok(())
    }
}

/// `~/.claude/projects/`: the standard Claude Code symlink
/// directory. Shared default for `install` and the
/// `vc-x1 symlink` subcommand.
fn default_symlink_dir() -> Result<PathBuf, Box<dyn std::error::Error>> {
    let home =
        std::env::var("HOME").map_err(|_| "HOME environment variable not set".to_string())?;
    Ok(PathBuf::from(home).join(".claude").join("projects"))
}

/// Install the standard Claude Code workspace symlink for `project_dir`.
///
/// Links `~/.claude/projects/<encoded>` -> `<project_dir>/.claude`.
/// Silent: caller is expected to announce the action (if desired)
/// and to include the resulting `SymLink` in any final summary
/// output.
///
/// Shared by `vc-x1 clone --scope=work,bot` and `vc-x1 init
/// --scope=work,bot`. The full `vc-x1 symlink` subcommand below
/// can't directly call `install`: it has different
/// responsibilities (`--target` / `--symlink-dir` overrides,
/// replace prompts, `--list`, and `sl.create(true)` vs `false`),
/// but both share `default_symlink_dir` for default-path
/// computation.
pub fn install(project_dir: &Path) -> Result<SymLink, Box<dyn std::error::Error>> {
    let sl = SymLink::new(
        project_dir,
        &default_bot_target(project_dir),
        &default_symlink_dir()?,
    )?;
    sl.create(false)?;
    Ok(sl)
}

/// Default symlink target: the workspace config's bot dir name,
/// honoring a legacy-schema declaration (the clone
/// backward-compat path), falling back to `.claude` when no
/// config resolves (e.g. mid-init before both sides exist).
fn default_bot_target(project_dir: &Path) -> PathBuf {
    crate::common::configured_bot_dir(project_dir)
        .ok()
        .flatten()
        .or_else(|| crate::legacy_vc_config::configured_bot_dir(project_dir))
        .and_then(|p| p.file_name().map(PathBuf::from))
        .unwrap_or_else(|| PathBuf::from(".claude"))
}

